#pragma once
/* 5x8 font with Ukrainian Cyrillic (generated by tools/font2c.py) and UTF-8 decoding. */
#include <stdint.h>

/* Next code point from *s, advancing it. 0 at the terminating NUL (not advanced).
 * Invalid or truncated sequence: U+FFFD, advanced by one byte. */
uint32_t utf8_next(const char **s);

/* 5 column bytes, bit 0 = top pixel. Unknown code point: glyph of '?'. */
const uint8_t *font5x8_glyph(uint32_t cp);
